  for(const sign of [-1,1]){const tip=new THREE.Mesh(new THREE.ConeGeometry(arrowSize*.35,arrowSize,12),new THREE.MeshBasicMaterial({color:0x172033}));tip.position.y=sign*axisExtent;if(sign<0)tip.rotation.z=Math.PI;group.add(tip)}
  label('eje',[0,axisExtent-arrowSize,0]);if($('revShowGenerator').checked)line(p.curve.map(([x,y])=>[x,y,0]),0xe67725);if(phi>1e-8||$('revShowGenerator').checked)line(curve.map(([x,y])=>[x*Math.cos(phi),y,x*Math.sin(phi)]),0xc65916);
  if($('revShowReferences').checked){const source=mode==='volume'?p.region:p.curve;const endpoints=[source[0],source.at(-1)];endpoints.forEach(([x,y],i)=>{const marker=new THREE.Mesh(new THREE.SphereGeometry(Math.max(maxY,maxX)*.022,10,8),new THREE.MeshBasicMaterial({color:0x173d9e,depthTest:false}));marker.position.set(x*Math.cos(phi),y,x*Math.sin(phi));marker.renderOrder=10;group.add(marker);label(i?'B':'A',marker.position.toArray())})}
  if(mode==='volume'){if($('revShowGenerator').checked)shape(p.region,0,0xf0af59,.5);if(phi>1e-8||$('revShowGenerator').checked)shape(p.region,phi,0xf0af59,.65)}
