  if($('revShowPath').checked)line(Array.from({length:97},(_,i)=>[cx*Math.cos(i*Math.PI/48),cy,cx*Math.sin(i*Math.PI/48)]),0xc52c3e,true);line([[0,cy,0],[cx*Math.cos(phi),cy,cx*Math.sin(phi)]],0xc52c3e);const dot=new THREE.Mesh(new THREE.SphereGeometry(Math.max(maxX,maxY)*.035,12,8),new THREE.MeshBasicMaterial({color:0xc52c3e,depthTest:false}));dot.position.set(cx*Math.cos(phi),cy,cx*Math.sin(phi));group.add(dot);label(mode==='volume'?'G_A':'G_L',[cx*Math.cos(phi),cy+.2,cx*Math.sin(phi)]);label('d',[cx*Math.cos(phi)/2,cy-.2,cx*Math.sin(phi)/2]);
  $('revAngleText').textContent=`${fmt(angle)}°`;$('revAngle').value=angle;const amount=mode==='surface'?p.surface:p.volume,base=mode==='surface'?p.length:p.area,d=mode==='surface'?p.lx:p.cx;
  $('revResults').innerHTML=`<article><h3>${mode==='surface'?'Longitud de la curva L':'Área de la región A'}</h3><strong>${fmt(base)} cm${mode==='surface'?'':'²'}</strong></article><article><h3>Distancia del centroide al eje d</h3><strong>${fmt(d)} cm</strong></article><article><h3>${mode==='surface'?'Superficie generada':'Volumen generado'}</h3>${math(`${mode==='surface'?'S':'V'}=(${base.toPrecision(6)})(${d.toPrecision(6)})\\left(\\frac{${Math.round(angle)}\\pi}{180}\\right)`)}<strong>≈ ${fmt(amount*angle/360)} cm${mode==='surface'?'²':'³'}</strong></article>`;
  $('revScope').textContent=mode==='surface'&&['cylinder','cone'].includes($('revKind').value)?'Se gira solo el lado exterior: el resultado es área lateral, no área total con bases. Para obtener las bases hay que girar también los segmentos horizontales.':'En región → volumen, las tapas planas de un giro parcial no se incluyen como áreas en la fórmula del volumen.';
